25	int32_t pw_bnep_parse(const uint8_t *buf, uint32_t len, struct pw_bnep_hdr *out)
26	{
27	  uint8_t t;
28	
29	  if (buf == NULL || out == NULL || len < 1)
30	    {
31	      return -EINVAL;
32	    }
33	
34	  memset(out, 0, sizeof(*out));
35	  t = buf[0];
36	
37	  /* 控制包：低 5 位恒为 0x01，高 3 位是 UUID 长度码 */
38	  if ((t & 0x1f) == PW_BNEP_CONTROL)
39	    {
40	      if (len < 2)
41	        {
42	          return -EINVAL;
43	        }
44	
45	      out->type      = PW_BNEP_CONTROL;
46	      out->uuid_code = (uint8_t)(t >> 5);
47	      out->ctl       = buf[1];
48	      out->payload   = buf + 2;
49	      out->paylen    = len - 2;
50	      return (int32_t)len;
51	    }
52	
53	  /* 数据包：高 3 位必须为 0 */
54	  if (t > PW_BNEP_COMPRESSED_DST_ONLY)
55	    {
56	      return -EINVAL;
57	    }
58	
59	  out->type = t;
60	
61	  switch (t)
62	    {
63	      case PW_BNEP_GENERAL_ETHERNET:
64	        if (len < PW_BNEP_HDR_LEN)
65	          {
66	            return -EINVAL;
67	          }
68	
69	        out->eth    = buf + 1;
70	        out->ethlen = len - 1;
71	        return (int32_t)len;
72	
73	      case PW_BNEP_COMPRESSED:
74	        /* 1 + dst(6) + src(6) + vlan(4) + ethertype(2) */
75	        if (len < (uint32_t)(PW_BNEP_HDR_LEN + PW_BNEP_VLAN_LEN))
76	          {
77	            return -EINVAL;
78	          }
79	
80	        return -EOPNOTSUPP;
81	
82	      case PW_BNEP_COMPRESSED_SRC_ONLY:
83	        if (len < (uint32_t)(PW_BNEP_HDR_LEN + PW_BNEP_VLAN_LEN -
84	                             PW_BNEP_ETH_ADDR_LEN))
85	          {
86	            return -EINVAL;
87	          }
88	
89	        return -EOPNOTSUPP;
90	
91	      case PW_BNEP_COMPRESSED_DST_ONLY:
92	        if (len < (uint32_t)(PW_BNEP_HDR_LEN + PW_BNEP_VLAN_LEN -
93	                             PW_BNEP_ETH_ADDR_LEN))
94	          {
95	            return -EINVAL;
96	          }
97	
98	        return -EOPNOTSUPP;
99	
100	      default:
101	        return -EINVAL;
102	    }
103	}
