105	int32_t pw_bnep_build_setup_req(uint8_t *buf, uint32_t cap,
106	                               uint16_t src_uuid, uint16_t dst_uuid)
107	{
108	  if (buf == NULL || cap < 6)
109	    {
110	      return -EINVAL;
111	    }
112	
113	  /* 类型字节：CONTROL(0x01) | uuid16 码(1) << 5 = 0x21 */
114	  buf[0] = (uint8_t)(PW_BNEP_CONTROL | (PW_BNEP_UUID16 << 5));
115	  buf[1] = PW_BNEP_CTL_SETUP_REQ;
116	  bnep_put_be16(&buf[2], dst_uuid);   /* 先目的（NAP） */
117	  bnep_put_be16(&buf[4], src_uuid);   /* 再源（PANU） */
118	  return 6;
119	}
