121	int32_t pw_bnep_parse_setup_rsp(const uint8_t *buf, uint32_t len, uint16_t *code)
122	{
123	  if (buf == NULL || code == NULL || len < 4)
124	    {
125	      return -EINVAL;
126	    }
127	
128	  if ((buf[0] & 0x1f) != PW_BNEP_CONTROL || buf[1] != PW_BNEP_CTL_SETUP_RSP)
129	    {
130	      return -EINVAL;
131	    }
132	
133	  *code = bnep_be16(&buf[2]);
134	  return 0;
135	}
