137	int32_t pw_bnep_build_filter_set(uint8_t *buf, uint32_t cap,
138	                                 const struct pw_bnep_ftype *ranges, uint8_t nranges)
139	{
140	  uint32_t need = 2u + (uint32_t)nranges * 4u;
141	  uint8_t  i;
142	
143	  if (buf == NULL || ranges == NULL || nranges == 0 || cap < need)
144	    {
145	      return -EINVAL;
146	    }
147	
148	  buf[0] = PW_BNEP_CONTROL;              /* 不带 UUID */
149	  buf[1] = PW_BNEP_CTL_FILTER_SET;
150	
151	  for (i = 0; i < nranges; i++)
152	    {
153	      bnep_put_be16(&buf[2 + i * 4], ranges[i].start);
154	      bnep_put_be16(&buf[2 + i * 4 + 2], ranges[i].end);
155	    }
156	
157	  return (int32_t)need;
158	}
159	
160	int32_t pw_bnep_parse_filter_rsp(const uint8_t *buf, uint32_t len, uint16_t *code)
161	{
162	  if (buf == NULL || code == NULL || len < 4)
163	    {
164	      return -EINVAL;
165	    }
166	
167	  if ((buf[0] & 0x1f) != PW_BNEP_CONTROL || buf[1] != PW_BNEP_CTL_FILTER_RSP)
168	    {
169	      return -EINVAL;
170	    }
171	
172	  *code = bnep_be16(&buf[2]);
173	  return 0;
174	}
175	
176	int32_t pw_bnep_build_data(uint8_t *buf, uint32_t cap, const uint8_t *eth,
177	                           uint32_t ethlen)
178	{
179	  if (buf == NULL || eth == NULL || ethlen < PW_BNEP_HDR_LEN - 1 ||
180	      cap < ethlen + 1u)
181	    {
182	      return -EINVAL;
183	    }
184	
185	  buf[0] = PW_BNEP_GENERAL_ETHERNET;
186	  memcpy(&buf[1], eth, ethlen);
187	  return (int32_t)(ethlen + 1u);
188	}
